# TC-C3BFFA7E-01: Verify that a system can show a confirmation message after a successful order
# AI-generated by mock-1 (prompt sg-v2); review before relying on it.
from pages.shop_page import ShopPage


def test_tc_c3bffa7e_01(page, base_url):
    screen = ShopPage(page, base_url)
    screen.open('/')
    screen.type('username', 'demo.user@example.test')
    screen.type('password', 'demo.user@example.test')
    screen.click('login_button')
    screen.click('add_backpack')
    screen.click('cart_link')
    screen.click('checkout_button')
    screen.type('ship_name', 'demo.user@example.test')
    screen.click('place_order')
    screen.assert_visible('confirmation')
